INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'escape-del-zoologico', 'Escape del Zoológico', 'Dinámica de atención acústica y reflejos zoológicos donde los scouts reaccionan imitando el sonido y marcha del animal asignado.', '<h2>📜 Descripción de Escape del Zoológico</h2>
<p><b>Escape del Zoológico</b> es una dinámica de concentración auditiva, respuesta rápida e integración grupal. Todos los participantes se organizan en círculo y reciben en secreto el nombre de un animal salvaje o doméstico (ej. <i>''León''</i>, <i>''Elefante''</i>, <i>''Lobo''</i> o <i>''Mono''</i>). El animador o Guardián del Zoo se ubica en el centro y comienza a relatar una visita guiada por la reserva natural. Cada vez que menciona a una especie (o grita <i>''¡Escape general del Zoológico!''</i>), todos los beneficiarios asignados a ese animal deben ponerse de pie de un salto, emitir su rugido o clamor característico y cambiar de asiento rápidamente sin perder el turno.</p>
<p>Esta actividad estimula la velocidad de reacción, la atención focalizada y la diversión compartida en Manada, Compañía, Tropa, Avanzada y Clan.</p>

<h2>🎲 ¿Cómo se juega Escape del Zoológico?</h2>
<p>Para llevar a cabo la dinámica con dinamismo y entusiasmo, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Formación y Asignación:</b> La unidad se sienta en sillas o marcas en el suelo; el animador asigna 3 o 4 especies repetitivamente.</li>
  <li><b>Narración del Guardián:</b> El dirigente relata una historia de campamento donde transitan distintas especies.</li>
  <li><b>El Clamor de la Fauna:</b> Al escuchar su especie, los scouts deben rugir/clamar y correr a ocupar un asiento desocupado.</li>
  <li><b>El Gran Escape:</b> Si el Guardián exclama <i>''¡Escape general del Zoológico!''</i>, absolutamente todos los participantes deben cambiar de lugar al unísono.</li>
  <li><b>Rotación de Guardianes:</b> El scout que quede sin asiento asume el rol de Guardián para continuar la narración.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de Escape del Zoológico</h2>
<p>La actividad valora los reflejos y la expresividad auditiva en el Tally:</p>
<ul>
  <li><b>Mayor Rapidez de Reacción:</b> Otorgar 5 puntos a la patrulla cuyos miembros cambien de lugar en el menor tiempo.</li>
  <li><b>Fidelidad del Clamor:</b> Otorgar 3 puntos al participante que interprete la rugido o voz animal con mayor entusiasmo.</li>
  <li><b>Atención Impecable:</b> Otorgar 3 puntos a los equipos que no tengan distracciones ni falsas salidas.</li>
</ul>', '/uploads/escape-del-zoologico.webp', 'publicado', '{"areas": ["creatividad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Sin Materiales"], "objetivos": ["Estimular la atención a los detalles", "Desarrollar la motricidad", "Reforzar el poner atención", "Crear un ambiente de distensión"], "justificacion_areas": "Escape del Zoológico potencia la creatividad al exigir la traducción sonora e imitación dramática de especies animales en tiempo real. Desarrolla la sociabilidad al afianzar la integración de la unidad, la agilidad en la rotación de lugares y el disfrute compartido sin discriminación desde Manada hasta Clan.", "variaciones": "<b>Zoo Nocturno a Ciegas:</b> Realizar los cambios de asiento utilizando únicamente las voces y rugidos de los compañeros.<br><b>Zoo de Especies en Peligro:</b> Asignar especies de la fauna nativa chilena (Puma, Huemul, Chinchilla, Pudú).<br><b>Zoo de Movimiento Lento:</b> Los desplazamientos se realizan en cámara lenta imitando la marcha del animal.", "recomendaciones": "Mantener las sillas o marcas a una distancia prudente para evitar tropezones durante los cambios rápidos. Fomentar la inclusión activa.", "objetivos_educativos": [{"id": "ec280dd0-2d80-4b84-86ad-2d362da14886", "area": "Creatividad", "unidad": "Manada", "texto": "Me gusta participar en juegos de observación.", "como_se_cumple": "Escuchando con atención focalizada la mención de la especie animal en el relato."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "unidad": "Manada", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "como_se_cumple": "Reaccionando de inmediato al llamado de la fauna para cambiar de puesto."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Respetando las normas de rotación y respeto durante los desplazamientos."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Integrándose con entusiasmo con cualquier seisena durante los cambios de lugar."}, {"id": "12686e7d-d6af-4c74-928d-c859d5b883d5", "area": "Creatividad", "unidad": "Compañía", "texto": "Ayudo en la preparación de los temas que discutimos en mi patrulla.", "como_se_cumple": "Aportando creatividad sonora y dramática en la imitación de especies."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Anticipando los espacios desocupados en el círculo para reubicar al equipo."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Demostrando juego limpio y cuidado físico hacia las compañeras."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Fomentando el buen humor y la camaradería ante los cambios improvisados."}, {"id": "e465926e-deed-4341-956f-047f56860e5e", "area": "Creatividad", "unidad": "Tropa", "texto": "Ayudo en la preparación de los temas que discutimos en mi patrulla.", "como_se_cumple": "Liderando relatos dinámicos en el rol de Guardián del Zoo."}, {"id": "3d0dff9b-11cd-4a30-b3a6-ec011ad95062", "area": "Creatividad", "unidad": "Tropa", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Sintetizando claves de respuesta veloz ante consignas múltiples."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Manteniendo el orden y el espíritu scout en la competencia."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Promoviendo la fraternidad y el aliento constante entre patrullas."}, {"id": "ed17d59c-1c64-4080-a206-bbe72eeae5a4", "area": "Creatividad", "unidad": "Avanzada", "texto": "Expresa lo que piensa y siente a través de distintos medios, creando en los ambientes en que actúa espacios gratos que faciliten el encuentro y el perfeccionamiento entre las personas.", "como_se_cumple": "Favoreciendo la animación cómica y la soltura expresiva en la Avanzada."}, {"id": "3fd19eb4-737c-43c5-9ea8-5e5307ce0309", "area": "Sociabilidad", "unidad": "Avanzada", "texto": "Cumple las normas que la sociedad se ha dado, evaluándolas con responsabilidad y sin renunciar a cambiarlas.", "como_se_cumple": "Fomentando el respeto y la inclusión responsable en dinámicas de gran grupo."}, {"id": "ef75fbed-4a6d-49ea-bfab-f2952415e1a0", "area": "Creatividad", "unidad": "Clan", "texto": "Actúa con agilidad mental ante las situaciones más diversas, desarrollando su capacidad de pensar, innovar y aventurar.", "como_se_cumple": "Demostrando agilidad mental e improvisación en relatos de animación Rover."}, {"id": "b5954f1c-4d0d-4bdb-97d8-821583beb77e", "area": "Sociabilidad", "unidad": "Clan", "texto": "Cumple las normas que la sociedad se ha dado, evaluándolas con responsabilidad y sin renunciar a cambiarlas.", "como_se_cumple": "Viviendo el servicio y la fraternidad alegre en el Clan."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

